  `contact_info` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `supplier` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `material_code` (`material_code`) USING BTREE,
  KEY `idx_material_code` (`material_code`) USING BTREE,
  KEY `idx_material_name` (`name`) USING BTREE,
  KEY `idx_material_category` (`category`) USING BTREE,
  KEY `idx_material_location` (`location`) USING BTREE
